    c.state().facts.insert("action:90",{"action:90","skill_study","cultivation"});
    ApprenticeshipReply accepted;accepted.proposal_id="apprenticeship:1";accepted.actor_id="student";accepted.decision="accepted";accepted.tick=2;accepted.revision=1;source.tick=2;source.revision=1;accepted.confirmation=source;state.replies.insert("apprenticeship:3",accepted);c.state().facts.insert("apprenticeship:3",{"apprenticeship:3",accepted.kind,"family_apprenticeship"});state.commits.insert("apprenticeship:3",{"result:4","student","family_apprenticeship_reply",2,2,{}});
    c.state().facts.insert("action:5",{"action:5","skill_study","cultivation"});
